using System.Text.Json.Nodes;
using CcDirector.Core.Configuration;
using CcDirector.Core.Utilities;

namespace CcDirector.Core.Browsers;

/// <summary>
/// The remembered "Open in Browser" default: which browser exe and profile folder a plain click
/// on the terminal's "Open in Browser" item should reopen. Stored in <c>config.json</c> under
/// <c>browser.default</c> so it survives an app restart.
/// </summary>
public sealed record BrowserDefault(string ExePath, string ProfileFolder);

/// <summary>
/// Reads and writes the remembered <see cref="BrowserDefault"/> in <c>config.json</c> (via
/// <see cref="CcDirectorConfigService"/>, so other config sections are preserved), and resolves a
/// stored exe path back to a live <see cref="BrowserInfo"/>.
/// </summary>
public static class BrowserDefaultStore
{
    /// <summary>
    /// Returns the remembered default, or null if the user has never chosen a browser+profile.
    /// A null result legitimately means "use the OS default" - it is not an error.
    /// </summary>
    public static BrowserDefault? Load()
    {
        var root = CcDirectorConfigService.ReadRaw();
        if (root["browser"]?["default"] is not JsonObject def)
            return null;

        var exePath = (string?)def["exePath"];
        var profileFolder = (string?)def["profileFolder"];
        if (string.IsNullOrWhiteSpace(exePath) || string.IsNullOrWhiteSpace(profileFolder))
            return null;

        return new BrowserDefault(exePath, profileFolder);
    }

    /// <summary>Persists <paramref name="value"/> as the remembered default in config.json.</summary>
    public static void Save(BrowserDefault value)
    {
        if (value is null) throw new ArgumentNullException(nameof(value));

        FileLog.Write($"[BrowserDefaultStore] Save: exe={value.ExePath}, profile={value.ProfileFolder}");
        var patch = new JsonObject
        {
            ["browser"] = new JsonObject
            {
                ["default"] = new JsonObject
                {
                    ["exePath"] = value.ExePath,
                    ["profileFolder"] = value.ProfileFolder,
                }
            }
        };
        CcDirectorConfigService.MergePatch(patch);
    }

    /// <summary>
    /// Returns the remembered default for the repository at <paramref name="repoPath"/>, or null if
    /// that repository has never chosen a browser+profile. A null result legitimately means "no
    /// repository default" - it is not an error; the caller falls back to the global default.
    /// Stored in config.json under <c>browser.repoDefaults.&lt;canonical repo path&gt;</c>, separate
    /// from the global <c>browser.default</c>.
    /// </summary>
    public static BrowserDefault? LoadForRepo(string repoPath)
    {
        if (string.IsNullOrWhiteSpace(repoPath))
            throw new ArgumentException("Repo path is required", nameof(repoPath));

        var key = NormalizeRepoKey(repoPath);
        FileLog.Write($"[BrowserDefaultStore] LoadForRepo: repo={repoPath}, key={key}");

        var root = CcDirectorConfigService.ReadRaw();
        if (root["browser"]?["repoDefaults"]?[key] is not JsonObject def)
        {
            FileLog.Write($"[BrowserDefaultStore] LoadForRepo: no repo default for key={key}");
            return null;
        }

        var exePath = (string?)def["exePath"];
        var profileFolder = (string?)def["profileFolder"];
        if (string.IsNullOrWhiteSpace(exePath) || string.IsNullOrWhiteSpace(profileFolder))
        {
            FileLog.Write($"[BrowserDefaultStore] LoadForRepo: incomplete repo default for key={key}");
            return null;
        }

        FileLog.Write($"[BrowserDefaultStore] LoadForRepo: exe={exePath}, profile={profileFolder}");
        return new BrowserDefault(exePath, profileFolder);
    }

    /// <summary>
    /// Persists <paramref name="value"/> as the remembered default for the repository at
    /// <paramref name="repoPath"/>. Writes ONLY under
    /// <c>browser.repoDefaults.&lt;canonical repo path&gt;</c>; the deep-merge leaves the global
    /// <c>browser.default</c> and every other repository's default untouched.
    /// </summary>
    public static void SaveForRepo(string repoPath, BrowserDefault value)
    {
        if (string.IsNullOrWhiteSpace(repoPath))
            throw new ArgumentException("Repo path is required", nameof(repoPath));
        if (value is null) throw new ArgumentNullException(nameof(value));

        var key = NormalizeRepoKey(repoPath);
        FileLog.Write($"[BrowserDefaultStore] SaveForRepo: repo={repoPath}, key={key}, exe={value.ExePath}, profile={value.ProfileFolder}");

        var patch = new JsonObject
        {
            ["browser"] = new JsonObject
            {
                ["repoDefaults"] = new JsonObject
                {
                    [key] = new JsonObject
                    {
                        ["exePath"] = value.ExePath,
                        ["profileFolder"] = value.ProfileFolder,
                    }
                }
            }
        };
        CcDirectorConfigService.MergePatch(patch);
    }

    /// <summary>
    /// Resolves the browser+profile default that should apply for a session belonging to the
    /// repository at <paramref name="repoPath"/>, in order: (1) the repository default, (2) the
    /// application-wide default, (3) null. A null result legitimately means "no remembered default"
    /// - the caller uses the OS default browser. When <paramref name="repoPath"/> is null or empty
    /// (a session with no repository) this is simply the global <see cref="Load"/>.
    /// </summary>
    public static BrowserDefault? Resolve(string? repoPath)
    {
        if (string.IsNullOrWhiteSpace(repoPath))
        {
            FileLog.Write("[BrowserDefaultStore] Resolve: no repo, using global default");
            return Load();
        }

        FileLog.Write($"[BrowserDefaultStore] Resolve: repo={repoPath}");
        var repoDefault = LoadForRepo(repoPath);
        if (repoDefault is not null)
        {
            FileLog.Write("[BrowserDefaultStore] Resolve: using repo default");
            return repoDefault;
        }

        FileLog.Write("[BrowserDefaultStore] Resolve: no repo default, falling back to global default");
        return Load();
    }

    /// <summary>
    /// The one canonical form of a repository path used as the config key, so the SAME repository
    /// maps to the SAME key regardless of trailing slash, forward vs back slashes, or (on Windows)
    /// letter case. Both <see cref="LoadForRepo"/> and <see cref="SaveForRepo"/> go through here so
    /// the rule lives in exactly one place.
    /// </summary>
    private static string NormalizeRepoKey(string repoPath)
    {
        var normalized = repoPath.Trim().Replace('\\', '/');
        normalized = normalized.TrimEnd('/');
        return normalized.ToLowerInvariant();
    }

    /// <summary>
    /// Resolves a stored exe path to a currently-installed <see cref="BrowserInfo"/>. Throws (no
    /// silent fallback) if that browser is no longer installed, so the caller can surface a clear
    /// error rather than opening some other browser.
    /// </summary>
    /// <exception cref="FileNotFoundException">No installed browser matches the stored exe path.</exception>
    public static BrowserInfo ResolveBrowser(string exePath)
    {
        if (string.IsNullOrWhiteSpace(exePath))
            throw new ArgumentException("Exe path is required", nameof(exePath));

        var match = BrowserLauncher.DetectBrowsers()
            .FirstOrDefault(b => string.Equals(b.ExePath, exePath, StringComparison.OrdinalIgnoreCase));

        if (match is null)
            throw new FileNotFoundException(
                $"The remembered browser is no longer installed at {exePath}.", exePath);

        return match;
    }
}

